import json,os
def transform(g):
    # find divider: full row or column of a single non-zero color
    H,W=len(g),len(g[0])
    for i,row in enumerate(g):
        if all(x!=0 for x in row) and len(set(row))==1 and row[0] not in (g[0][0],):
            pass
    # generic: find divider row (all same nonzero, spanning width) or col
    div=None; axis=None
    for i in range(H):
        row=g[i]
        if len(set(row))==1 and row[0]!=0 and all(x==row[0] for x in row):
            # ensure it separates into two equal parts? just use it
            div=i; axis='row'; break
    if div is None:
        for j in range(W):
            col=[g[i][j] for i in range(H)]
            if len(set(col))==1 and col[0]!=0:
                div=j; axis='col'; break
    if axis=='row':
        A=[r for r in g[:div]]; B=[r for r in g[div+1:]]
    else:
        A=[r[:div] for r in g]; B=[r[div+1:] for r in g]
    return [[2 if (A[i][j]!=0 and B[i][j]!=0) else 0 for j in range(len(A[0]))] for i in range(len(A))]

